// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadTitanOne = makeLoadFont('TitanOne');

// Library: none — using advanced DOM CSS 3D (preserve-3d + translateZ stacking) 
// to achieve a rich, thick 3D extrusion effect while satisfying the strict 
// Google Font loading requirements (which natively target the DOM, not WebGL).

const { fontFamily: titanOneFamily } = loadTitanOne();



export type Hover3DTextProps = Record<string, any>;

const Hover3DText: React.FC<Hover3DTextProps> = ({
  backgroundColor = "#132145",
  transparentBackground = false,
  durationInSeconds = 5,
  text = "FINISH",
  frontColor = "#68e3b1",
  sideColor = "#3da880",
  fontSize = 350,
  extrusionDepth = 40,
  hoverAmplitude = 25,
  hoverSpeed = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Entrance spring
  const entranceProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1.2 },
  });

  const entranceScale = interpolate(entranceProgress, [0, 1], [0, 1]);
  const entranceRotX = interpolate(entranceProgress, [0, 1], [45, 0]);
  const entranceOpacity = interpolate(frame, [0, 5], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Continuous hover oscillation
  const hoverTime = (frame / fps) * hoverSpeed;
  const hoverY = Math.sin(hoverTime * Math.PI) * hoverAmplitude * s;
  
  // Subtle 3D rotation over time to show off depth
  const rotX = Math.sin(hoverTime * Math.PI * 0.7) * 8;
  const rotY = Math.cos(hoverTime * Math.PI * 0.5) * 12;

  const totalRotX = entranceRotX + rotX;

  // Prepare Z-layers (reversed so the front layer renders last in DOM, guaranteeing it sits on top)
  const layers = useMemo(() => {
    return Array.from({ length: extrusionDepth })
      .map((_, i) => i)
      .reverse();
  }, [extrusionDepth]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      {/* Perspective Stage */}
      <div
        style={{
          width: "100%",
          height: "100%",
          perspective: `${1500 * s}px`,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          transition: "none",
        }}
      >
        {/* Centering Wrapper */}
        <div style={{ position: "relative", transition: "none" }}>
          
          {/* Floor Shadow */}
          <div
            style={{
              position: "absolute",
              width: `${fontSize * 1.5 * s}px`,
              height: `${fontSize * 0.2 * s}px`,
              borderRadius: "50%",
              backgroundColor: "#000000",
              filter: `blur(${20 * s}px)`,
              left: "50%",
              top: "100%",
              transform: `translate(-50%, ${60 * s}px) scale(${interpolate(
                hoverY,
                [-hoverAmplitude * s, hoverAmplitude * s],
                [0.8, 1.2],
                { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
              )})`,
              opacity:
                interpolate(
                  hoverY,
                  [-hoverAmplitude * s, hoverAmplitude * s],
                  [0.2, 0.6],
                  { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
                ) * entranceOpacity,
              transition: "none",
            }}
          />

          {/* 3D Text Geometry Stack */}
          <div
            style={{
              position: "relative",
              transformStyle: "preserve-3d",
              transform: `translateY(${hoverY}px) scale(${entranceScale}) rotateX(${totalRotX}deg) rotateY(${rotY}deg)`,
              opacity: entranceOpacity,
              transition: "none",
            }}
          >
            {layers.map((i) => {
              const isFront = i === 0;
              const isBack = i === extrusionDepth - 1;

              return (
                <div
                  key={i}
                  style={{
                    position: isFront ? "relative" : "absolute",
                    left: 0,
                    top: 0,
                    transform: `translateZ(${-i * 1.5 * s}px)`,
                    color: isFront ? frontColor : sideColor,
                    fontFamily: `${titanOneFamily}, sans-serif`,
                    fontSize: `${fontSize * s}px`,
                    lineHeight: 1,
                    fontWeight: 900,
                    letterSpacing: `${-2 * s}px`,
                    whiteSpace: "nowrap",
                    // Adding text-stroke to side layers thickens them slightly, creating a smooth, gapless bevel
                    WebkitTextStroke: isFront
                      ? "none"
                      : `${3 * s}px ${sideColor}`,
                    // Highlight on the top front edge, and drop shadow on the absolute back layer
                    textShadow: isFront
                      ? `0px ${-3 * s}px ${6 * s}px rgba(255,255,255,0.4)`
                      : isBack
                      ? `0px ${15 * s}px ${25 * s}px rgba(0,0,0,0.6)`
                      : "none",
                    transition: "none",
                  }}
                >
                  {text}
                </div>
              );
            })}
          </div>

        </div>
      </div>
    </AbsoluteFill>
  );
};

export default Hover3DText;